docker_build:needs:docker_lint name:ubuntu-latest - Docker - build runs-on:ubuntu-latest steps:uses:actions/checkout@v2 name:Set Environment Variables run:OWNER="$(echo "${{ github.repository_owner }}" | tr '[:upper:]' '[:lower:]' | tr -d '-')"
IMG=octobot
echo "VERSION=${GITHUB_REF##*/}" >> $GITHUB_ENV
echo "IMAGE=${OWNER}/${IMG}" >> $GITHUB_ENV
echo "LATEST=latest" >> $GITHUB_ENV
echo "STABLE=stable" >> $GITHUB_ENV
 name:Set up QEMU uses:docker/setup-qemu-action@v1 name:Set up Docker Buildx uses:docker/setup-buildx-action@v1 name:Login to DockerHub uses:docker/login-action@v1 with:username:${{ secrets.DOCKERHUB_USERNAME }} password:${{ secrets.DOCKERHUB_TOKEN }} name:Build if:github.event_name == 'push' && !startsWith(github.ref, 'refs/tags') && github.ref != 'refs/heads/dev' uses:docker/build-push-action@v2 with:context:. file:./Dockerfile platforms:linux/amd64 push:tags:${{ env.IMAGE }}:${{ env.LATEST }} name:Build and push latest if:github.event_name == 'push' && startsWith(github.ref, 'refs/tags') && github.ref == 'refs/heads/dev' uses:docker/build-push-action@v2 with:context:. platforms:linux/amd64,linux/arm/v7,linux/arm64 push:tags:${{ env.IMAGE }}:${{ env.LATEST }} name:Build and push on tag if:github.event_name == 'push' && startsWith(github.ref, 'refs/tags') uses:docker/build-push-action@v2 with:context:. file:./Dockerfile platforms:linux/amd64,linux/arm/v7,linux/arm64 push:tags:${{ env.IMAGE }}:${{ env.LATEST }}
${{ env.IMAGE }}:${{ env.STABLE }}
${{ env.IMAGE }}:${{ env.VERSION }}
 name:Image digest run:echo ${{ steps.docker_build.outputs.digest }}

