jobs:build_and_package:runs-on:ubuntu-latest defaults:run:shell:bash -l {0} steps:uses:actions/checkout@v2 name:Loading cache. uses:actions/cache@v2 id:cache with:path:~/.cache/pip key:v1-metadata restore-keys:v1-metadata-${{ hashFiles('setup.py') }}
v1-metadata
 name:Setup environment run:pip install git+https://github.com/huggingface/transformers#egg=transformers[dev]
 name:Update metadata run:python utils/update_metadata.py --token ${{ secrets.SYLVAIN_HF_TOKEN }} --commit_sha ${{ github.sha }}

build-compiler:name:build-${{matrix.config.name}} runs-on:${{matrix.config.os}} strategy:matrix:dotnet-version:7.0 config:name:x86_64-macos os:macos-latest shell:bash rid:osx-x64 buildType:Release name:x86_64-linux os:ubuntu-latest shell:bash rid:linux-x64 buildType:Release name:x86_64-windows os:windows-latest shell:bash rid:win-x64 buildType:Release steps:uses:actions/checkout@v2 name:Setup .NET uses:actions/setup-dotnet@v1 with:dotnet-version:${{matrix.dotnet-version}} name:Cache NuGet packages uses:actions/cache@v3 with:path:${{ github.workspace }}/.nuget/packages key:${{ runner.os }}-nuget-${{ hashFiles('**/packages.lock.json') }} restore-keys:${{ runner.os }}-nuget-
 name:Build run:dotnet restore -r ${{matrix.config.rid}}
dotnet publish src/Nncase.Compiler -c ${{matrix.config.buildType}} --no-restore --sc false -r ${{matrix.config.rid}}
 name:Upload nncase Build Artifact uses:actions/upload-artifact@v3 with:name:nncase-${{matrix.config.name}} path:${{github.workspace}}/src/Nncase.Compiler/bin/${{matrix.config.buildType}}/net${{matrix.dotnet-version}}/${{matrix.config.rid}}/publish if-no-files-found:error build-native:needs:build-compiler name:build-native-${{matrix.config.name}} runs-on:${{matrix.config.os}} strategy:matrix:dotnet-version:7.0 config:name:x86_64-macos os:macos-latest name:x86_64-linux os:ubuntu-latest name:x86_64-windows os:windows-latest arch:x64 env:VULKANSDK_VER:1.2.182.0 steps:uses:actions/checkout@v3 uses:seanmiddleditch/gha-setup-ninja@master name:Setup .NET uses:actions/setup-dotnet@v1 with:dotnet-version:${{matrix.dotnet-version}} name:Install nncase uses:actions/download-artifact@v3 with:name:nncase-${{matrix.config.name}} path:${{github.workspace}}/install name:Set up build environment (Windows, Visual Studio) uses:ilammy/msvc-dev-cmd@v1 with:arch:${{matrix.config.arch}} if:runner.os == 'Windows' name:Set up build environment (Macos) run:brew install sunnycase/core/libomp@11.1.0
 if:runner.os == 'Macos' name:Setup Python uses:actions/setup-python@v4 with:python-version:3.7 name:Install cibuildwheel run:pip install cibuildwheel name:Build wheel run:python -m cibuildwheel --output-dir wheelhouse name:Upload nncase-python Build Artifact uses:actions/upload-artifact@v3 with:name:nncase-python-${{matrix.config.name}} path:${{github.workspace}}/wheelhouse if-no-files-found:error

tests:runs-on:ubuntu-latest strategy:matrix:tf-version:1.13.1 1.14.0 1.15.0-rc2 2.0.0 steps:uses:actions/checkout@v1 name:Set up Python uses:actions/setup-python@v1 with:python-version:3.7 name:Install dependencies run:pip install tensorflow==${{matrix.tf-version}}
pip install -e .[test]
 name:Test with pytest run:pytest . coverage:runs-on:ubuntu-latest steps:uses:actions/checkout@v1 name:Set up Python uses:actions/setup-python@v1 with:python-version:3.6 name:Install dependencies run:pip install tensorflow==2.0.0
pip install -e .[test]
 name:Generate coverage report run:pytest . --cov=larq --cov-report=xml --cov-config=.coveragerc name:Upload coverage to Codecov run:curl -s https://codecov.io/bash | bash -s -- -t $token -f ./coverage.xml -F unittests env:token:${{secrets.CODECOV_TOKEN}}

jobs:verify:runs-on:ubuntu-latest strategy:matrix:python-version:3.8 3.9 poetry-version:1.1.14 test-group:1 2 3 4 if:${{ github.event.comment.body == 'test advanced'}} steps:name:Message Initiating uses:actions/github-script@v4 with:script:github.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: 'Launching advanced tests 🚀',
});          
 name:Get PR SHA id:sha uses:actions/github-script@v4 with:result-encoding:string script:const { owner, repo, number } = context.issue;
const pr = await github.pulls.get({
  owner,
  repo,
  pull_number: number,
});
return pr.data.head.sha      
 uses:actions/checkout@v2 with:ref:${{ steps.sha.outputs.result }} name:Set up Python ${{ matrix.python-version }} uses:actions/setup-python@v2 with:python-version:${{ matrix.python-version }} name:Install Poetry ${{ matrix.poetry-version }} uses:abatilo/actions-poetry@v2.0.0 with:poetry-version:${{ matrix.poetry-version }} name:Install Poetry Dynamic Versioning Plugin run:pip install poetry-dynamic-versioning name:Install graphviz run:sudo apt install graphviz libgraphviz-dev graphviz-dev pkg-config
 name:Install dependencies run:python -m pip install --upgrade pip
echo "installing poetry dependencies"
poetry install -E plotting -E causalml
 name:Run Advanced Tests run:poetry run poe test_advanced  --splits 4 --group ${{ matrix.test-group }} name:Message success if:${{ success() }} uses:actions/github-script@v4 with:script:github.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: 'Advanced tests succeeded! ✅',
});          
 name:Message failure if:${{ failure() }} uses:actions/github-script@v4 with:script:github.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: 'Advanced tests failed! ❌',
});

