jobs:unittest:runs-on:${{ matrix.os }} strategy:matrix:os:ubuntu-latest windows-latest macos-latest python-version:3.6 3.8 onnx-version:onnx==1.8.0 tensorflow-version:tensorflow-cpu==2.3.1 tensorflow-addons==0.11.2 include:os:ubuntu-latest python-version:3.6 onnx-version:onnx==1.7.0 tensorflow-version:tensorflow-cpu==2.3.1 tensorflow-addons==0.11.2 os:ubuntu-latest python-version:3.8 onnx-version:git+https://github.com/onnx/onnx.git@master tensorflow-version:tensorflow-cpu tensorflow-addons steps:name:Checkout ONNX-TF uses:actions/checkout@v2 name:Set up Python ${{ matrix.python-version }} uses:actions/setup-python@v2 with:python-version:${{ matrix.python-version }} name:Install protobuf if:${{ matrix.os == 'ubuntu-latest' && startsWith(matrix.onnx-version, 'git+') }} run:sudo apt-get install -y protobuf-compiler libprotoc-dev
 name:Install dependencies, ONNX ${{ matrix.onnx-version }} run:pip install pytest tabulate ${{ matrix.tensorflow-version }}
pip install ${{ matrix.onnx-version }}
pip install -e .
 name:Run Backend tests run:python -m unittest discover test -v

