name:Run all tests for the new model if:${{ needs.check_for_new_model.outputs.new_model != '' && contains(github.event.pull_request.labels.*.name, 'single-model-run-slow') }} needs:check_for_new_model strategy:fail-fast:matrix:folders:${{ needs.check_for_new_model.outputs.new_model }} machine_type:single-gpu multi-gpu runs-on:${{ matrix.machine_type }} nvidia-gpu t4 daily-ci container:image:huggingface/transformers-all-latest-gpu options:--gpus all --shm-size "16gb" --ipc host -v /mnt/cache/.cache/huggingface:/mnt/cache/ steps:name:Echo input and matrix info shell:bash run:echo "${{ matrix.folders }}"
 name:Echo folder ${{ matrix.folders }} shell:bash run:echo "${{ matrix.folders }}"
matrix_folders=${{ matrix.folders }}
matrix_folders=${matrix_folders/'models/'/'models_'}
echo "$matrix_folders"
echo "matrix_folders=$matrix_folders" >> $GITHUB_ENV
 name:Update clone working-directory:/transformers run:git fetch && git checkout ${{ github.event.pull_request.head.sha }} name:Reinstall transformers in edit mode (remove the one installed during docker image build) working-directory:/transformers run:python3 -m pip uninstall -y transformers && python3 -m pip install -e . name:NVIDIA-SMI run:nvidia-smi
 name:Environment working-directory:/transformers run:python3 utils/print_env.py
 name:Show installed libraries and their versions working-directory:/transformers run:pip freeze name:Run all tests on GPU working-directory:/transformers run:python3 -m pytest -v -rs --make-reports=${{ matrix.machine_type }}_tests_gpu_${{ matrix.folders }} tests/${{ matrix.folders }} name:Failure short reports if:${{ failure() }} continue-on-error:run:cat /transformers/reports/${{ matrix.machine_type }}_tests_gpu_${{ matrix.folders }}/failures_short.txt name:Make sure report directory exists shell:bash run:mkdir -p /transformers/reports/${{ matrix.machine_type }}_tests_gpu_${{ matrix.folders }}
echo "hello" > /transformers/reports/${{ matrix.machine_type }}_tests_gpu_${{ matrix.folders }}/hello.txt
echo "${{ matrix.machine_type }}_tests_gpu_${{ matrix.folders }}"
 name:Test suite reports artifacts: ${{ matrix.machine_type }}_run_all_tests_gpu_${{ env.matrix_folders }}_test_reports if:${{ always() }} uses:actions/upload-artifact@v4 with:name:${{ matrix.machine_type }}_run_all_tests_gpu_${{ env.matrix_folders }}_test_reports path:/transformers/reports/${{ matrix.machine_type }}_tests_gpu_${{ matrix.folders }}

stack-integration-tests-k8s:strategy:max-parallel:1 matrix:os:ubuntu-latest python-version:3.9 runs-on:${{ matrix.os }} steps:uses:actions/checkout@v2 name:Check for file changes uses:dorny/paths-filter@v2 id:changes with:token:${{ github.token }} filters:.github/file-filters.yml name:Set up Python ${{ matrix.python-version }} uses:actions/setup-python@v2 if:steps.changes.outputs.stack == 'true' with:python-version:${{ matrix.python-version }} name:Cache docker images uses:broadshield/action-docker-layer-caching@main if:steps.changes.outputs.stack == 'true' continue-on-error:with:filter:reference='openmined/*' name:Get pip cache dir if:steps.changes.outputs.stack == 'true' id:pip-cache run:echo "::set-output name=dir::$(pip cache dir)"
 name:pip cache uses:actions/cache@v2 if:steps.changes.outputs.stack == 'true' with:path:${{ steps.pip-cache.outputs.dir }} key:${{ runner.os }}-pip-py${{ matrix.python-version }} restore-keys:${{ runner.os }}-pip-py${{ matrix.python-version }}
 name:Upgrade pip if:steps.changes.outputs.stack == 'true' run:pip install --upgrade --user pip
 name:Install tox if:steps.changes.outputs.stack == 'true' run:pip install tox --upgrade
 name:Run integration tests if:steps.changes.outputs.stack == 'true' shell:bash run:curl -s -L "https://github.com/loft-sh/devspace/releases/latest" | sed -nE 's!.*"([^"]*devspace-linux-amd64)".*!https://github.com\1!p' | xargs -n 1 curl -L -o devspace && chmod +x devspace;
sudo install devspace /usr/local/bin;
tox -e stack.test.integration.k8s

