name:Install pytorch Windows if:startsWith(runner.os, 'Windows') env:TORCH_VERSION:${{ matrix.torch-version }} run:If ($env:TORCH_VERSION -eq "1.5.0") {
    $env:TORCHVISION_VERSION="0.6.0"
} Elseif ( $env:TORCH_VERSION -eq "1.5.1" ) {
    $env:TORCHVISION_VERSION="0.6.1"
} Elseif ($env:TORCH_VERSION -eq "1.6.0") {
    $env:TORCHVISION_VERSION="0.7"
} Elseif ($env:TORCH_VERSION -eq "1.7.0") {
    $env:TORCHVISION_VERSION="0.8.1"
}
pip install torch==$env:TORCH_VERSION+cpu torchvision==$env:TORCHVISION_VERSION+cpu -f https://download.pytorch.org/whl/torch_stable.html

name:Install pytorch Windows if:startsWith(runner.os, 'Windows') env:TORCH_VERSION:${{ matrix.torch-version }} run:If ($env:TORCH_VERSION -eq "1.5.0") {
    $env:TORCHVISION_VERSION="0.6.0"
} Elseif ( $env:TORCH_VERSION -eq "1.5.1" ) {
    $env:TORCHVISION_VERSION="0.6.1"
} Elseif ($env:TORCH_VERSION -eq "1.6.0") {
    $env:TORCHVISION_VERSION="0.7"
}
pip install torch==$env:TORCH_VERSION+cpu torchvision==$env:TORCHVISION_VERSION+cpu -f https://download.pytorch.org/whl/torch_stable.html

name:Build Wheel run:echo ::group::Set up Multibuild
source multibuild/common_utils.sh
source multibuild/travis_steps.sh
source config.sh
echo ::endgroup::
echo ::group::Before install
before_install
echo ::endgroup::
echo ::group::Build wheel
find . -type f -name "*.egg" -exec rm -v {} \;
build_wheel $REPO_DIR ${{ matrix.PLAT }}
echo ::endgroup::

name:Extract version and name shell:bash run:# extract version and name from patterm: pypi/<version>/<name>
echo ::set-output name=version::$(echo ${GITHUB_REF} | sed -E -e 's/refs\/heads\/pypi\/(.*)\/(develop|release)/\1/g')
echo ::set-output name=name::$(echo ${GITHUB_REF} | sed -E -e 's/refs\/heads\/pypi\/(.*)\/(develop|release)/\2/g')
 id:extract

steps:uses:actions/checkout@v1 name:Set the environment run:echo ::set-env name=GIT_COMMIT_ID::$(git describe --always --dirty)
echo ::set-env name=GIT_BRANCH_NAME::$(echo ${{ github.ref }} | cut -d/ -f3- | sed "s/[^[:alnum:]]//g")
echo ::set-env name=DOCKER_GID::$(getent group docker | cut -d: -f3)
 name:Build the containers run:make build
 name:Build the docs run:make docs
 name:Deploy the documentation on master if:github.ref == 'refs/heads/master' uses:peaceiris/actions-gh-pages@v3 with:github_token:${{ secrets.GITHUB_TOKEN }} publish_dir:./docs/_build/html

