steps:uses:actions/checkout@v2 name:Setup .NET uses:actions/setup-dotnet@v1 with:dotnet-version:${{matrix.dotnet-version}} name:Cache NuGet packages uses:actions/cache@v3 with:path:${{ github.workspace }}/.nuget/packages key:${{ runner.os }}-nuget-${{ hashFiles('**/packages.lock.json') }} restore-keys:${{ runner.os }}-nuget-
 name:Build run:dotnet restore -r ${{matrix.config.rid}}
dotnet publish src/Nncase.Compiler -c ${{matrix.config.buildType}} --no-restore --sc false -r ${{matrix.config.rid}}
 name:Upload nncase Build Artifact uses:actions/upload-artifact@v3 with:name:nncase-${{matrix.config.name}} path:${{github.workspace}}/src/Nncase.Compiler/bin/${{matrix.config.buildType}}/net${{matrix.dotnet-version}}/${{matrix.config.rid}}/publish if-no-files-found:error

