uses:actions/checkout@v2 name:Set Environment Variables run:OWNER="$(echo "${{ github.repository_owner }}" | tr '[:upper:]' '[:lower:]' | tr -d '-')"
IMG=octobot
echo "VERSION=${GITHUB_REF##*/}" >> $GITHUB_ENV
echo "IMAGE=${OWNER}/${IMG}" >> $GITHUB_ENV
echo "LATEST=latest" >> $GITHUB_ENV
echo "STABLE=stable" >> $GITHUB_ENV
 name:Set up QEMU uses:docker/setup-qemu-action@v1 name:Set up Docker Buildx uses:docker/setup-buildx-action@v1 name:Login to DockerHub uses:docker/login-action@v1 with:username:${{ secrets.DOCKERHUB_USERNAME }} password:${{ secrets.DOCKERHUB_TOKEN }} name:Build if:github.event_name == 'push' && !startsWith(github.ref, 'refs/tags') && github.ref != 'refs/heads/dev' uses:docker/build-push-action@v2 with:context:. file:./Dockerfile platforms:linux/amd64 push:tags:${{ env.IMAGE }}:${{ env.LATEST }} name:Build and push latest if:github.event_name == 'push' && startsWith(github.ref, 'refs/tags') && github.ref == 'refs/heads/dev' uses:docker/build-push-action@v2 with:context:. platforms:linux/amd64,linux/arm/v7,linux/arm64 push:tags:${{ env.IMAGE }}:${{ env.LATEST }} name:Build and push on tag if:github.event_name == 'push' && startsWith(github.ref, 'refs/tags') uses:docker/build-push-action@v2 with:context:. file:./Dockerfile platforms:linux/amd64,linux/arm/v7,linux/arm64 push:tags:${{ env.IMAGE }}:${{ env.LATEST }}
${{ env.IMAGE }}:${{ env.STABLE }}
${{ env.IMAGE }}:${{ env.VERSION }}
 name:Image digest run:echo ${{ steps.docker_build.outputs.digest }}

name:Create env.yml shell:bash run:python -m pip install --upgrade pip;
pip install conda-merge;
if [ "$(uname)" == 'Darwin' ]; then
  conda-merge env_jax.yml env.test.yml > env.yml
else
  conda-merge env_jax.yml env.test.yml > env.yml
fi;

name:Checkout repository uses:actions/checkout@v1 with:fetch-depth:1 name:Caching (for Linux) uses:actions/cache@v1 if:startsWith(runner.os, 'linux') with:path:~/.cache/pip key:${{ runner.os }}-pip-${{ hashFiles('**/requirements.txt') }} restore-keys:${{ runner.os }}-pip- name:Caching (for Macintosh) uses:actions/cache@v1 if:startsWith(runner.os, 'macos') with:path:~/Library/Caches/pip key:${{ runner.os }}-pip-${{ hashFiles('**/requirements.txt') }} restore-keys:${{ runner.os }}-pip- name:Caching (for Windows) uses:actions/cache@v1 if:startsWith(runner.os, 'windows') with:path:~\AppData\Local\pip\Cache key:${{ runner.os }}-pip-${{ hashFiles('**/requirements.txt') }} restore-keys:${{ runner.os }}-pip- name:Set up Python uses:actions/setup-python@v1 with:python-version:${{ matrix.python-version }} name:Initialize environment shell:bash run:python -m venv "${VENV_DIR}" name:Install packages shell:bash run:case "${{ matrix.os }}" in
  windows*) scripts="Scripts";;
  *       ) scripts="bin";;
esac
. "${VENV_DIR}/${scripts}/activate"
python -m pip install -r requirements.txt
 name:Run tests shell:bash run:case "${{ matrix.os }}" in
  windows*) scripts="Scripts";;
  *       ) scripts="bin";;
esac
. "${VENV_DIR}/${scripts}/activate"
echo "Using $(python --version) on ${{ matrix.os }}" 1>&2
nosetests --with-coverage tests

