run_tests_single_gpu:name:Model Tests on single GPU needs:setup if:contains(fromJson(needs.setup.outputs.matrix), 'dummy') != true strategy:fail-fast:matrix:folders:${{ fromJson(needs.setup.outputs.matrix) }} machines:single-gpu runs-on:self-hosted docker-gpu ${{ matrix.machines }} container:image:huggingface/transformers-all-latest-gpu options:--gpus 0 --shm-size "16gb" --ipc host -v /mnt/cache/.cache/huggingface:/mnt/cache/ steps:name:NVIDIA-SMI run:nvidia-smi
 name:Are GPUs recognized by our DL frameworks working-directory:/transformers run:utils/print_env_pt.py
TF_CPP_MIN_LOG_LEVEL=3 python3 -c "import tensorflow as tf; print('TF GPUs available:', bool(tf.config.list_physical_devices('GPU')))"
TF_CPP_MIN_LOG_LEVEL=3 python3 -c "import tensorflow as tf; print('Number of TF GPUs available:', len(tf.config.list_physical_devices('GPU')))"
 name:Echo folder ${{ matrix.folders }} shell:bash run:echo "${{ matrix.folders }}"
echo "${{ fromJson(needs.setup.outputs.test_map)[matrix.folders] }}"
matrix_folders=${{ matrix.folders }}
matrix_folders=${matrix_folders/'models/'/'models_'}
echo "$matrix_folders"
echo "matrix_folders=$matrix_folders" >> $GITHUB_ENV
 name:Update clone working-directory:/transformers run:git fetch && git checkout ${{ github.sha }} name:Run all non-slow selected tests on GPU working-directory:/transformers run:python3 -m pytest -n 2 --dist=loadfile -v --make-reports=${{ matrix.machines }}_tests_gpu_${{ matrix.folders }} ${{ fromJson(needs.setup.outputs.test_map)[matrix.folders] }}
 name:Failure short reports if:${{ failure() }} continue-on-error:run:cat /transformers/reports/${{ matrix.machines }}_tests_gpu_${{ matrix.folders }}/failures_short.txt name:Test suite reports artifacts if:${{ always() }} uses:actions/upload-artifact@v2 with:name:${{ matrix.machines }}_run_all_tests_gpu_${{ env.matrix_folders }}_test_reports path:/transformers/reports/${{ matrix.machines }}_tests_gpu_${{ matrix.folders }}

