verify:runs-on:ubuntu-latest strategy:matrix:python-version:3.8 3.9 poetry-version:1.1.14 test-group:1 2 3 4 if:${{ github.event.comment.body == 'test advanced'}} steps:name:Message Initiating uses:actions/github-script@v4 with:script:github.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: 'Launching advanced tests 🚀',
});          
 name:Get PR SHA id:sha uses:actions/github-script@v4 with:result-encoding:string script:const { owner, repo, number } = context.issue;
const pr = await github.pulls.get({
  owner,
  repo,
  pull_number: number,
});
return pr.data.head.sha      
 uses:actions/checkout@v2 with:ref:${{ steps.sha.outputs.result }} name:Set up Python ${{ matrix.python-version }} uses:actions/setup-python@v2 with:python-version:${{ matrix.python-version }} name:Install Poetry ${{ matrix.poetry-version }} uses:abatilo/actions-poetry@v2.0.0 with:poetry-version:${{ matrix.poetry-version }} name:Install Poetry Dynamic Versioning Plugin run:pip install poetry-dynamic-versioning name:Install graphviz run:sudo apt install graphviz libgraphviz-dev graphviz-dev pkg-config
 name:Install dependencies run:python -m pip install --upgrade pip
echo "installing poetry dependencies"
poetry install -E plotting -E causalml
 name:Run Advanced Tests run:poetry run poe test_advanced  --splits 4 --group ${{ matrix.test-group }} name:Message success if:${{ success() }} uses:actions/github-script@v4 with:script:github.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: 'Advanced tests succeeded! ✅',
});          
 name:Message failure if:${{ failure() }} uses:actions/github-script@v4 with:script:github.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: 'Advanced tests failed! ❌',
});

