test-suite:runs-on:ubuntu-latest needs:build strategy:matrix:test:tests/test_suite.py include:test:tests/test_suite.py POST_TASK:" steps:uses:actions/checkout@v2 name:Make run:mkdir install name:Download Artifacts uses:actions/download-artifact@v2 name:Extract Webots run:tar xjf artifact/webots-*-x86-64.tar.bz2 -C artifact
 name:Install Webots Dependencies run:sudo apt -y install g++ make ffmpeg libavcodec-extra libglu1-mesa libxkbcommon-x11-dev execstack libusb-dev libxcb-keysyms1 libxcb-image0 libxcb-icccm4 libxcb-randr0 libxcb-render-util0 libxcb-xinerama0 name:Set up Python 3.8 uses:actions/setup-python@v2 with:python-version:3.8 name:${{ matrix.test }} run:export LIBGL_ALWAYS_SOFTWARE=true
export WEBOTS_HOME=$PWD/artifact/webots
xvfb-run --auto-servernum python ${{ matrix.test }}
${{ matrix.POST_TASK }}

